import subprocess, time
from collections import defaultdict, deque
for i in range(36):
    print(f'--- appserver-sample {i} ---', flush=True)
    ps = subprocess.check_output(['ps','-axo','pid=,ppid=,etime=,stat=,command='], text=True, errors='replace')
    children = defaultdict(list)
    rows = {}
    for line in ps.splitlines():
        parts = line.strip().split(None, 4)
        if len(parts) < 5:
            continue
        pid, ppid = int(parts[0]), int(parts[1])
        rows[pid] = parts
        children[ppid].append(pid)
    for root in [81212, 84156]:
        q = deque([(root,0)])
        seen = set()
        while q:
            pid, depth = q.popleft()
            if pid in seen:
                continue
            seen.add(pid)
            row = rows.get(pid)
            if row and (depth <= 1 or 'codex' in row[4].lower() or 'bun' in row[4].lower()):
                pid_s, ppid_s, etime, stat, cmd = row
                print(f"PS {'  '*depth}{pid_s} ppid={ppid_s} etime={etime} stat={stat} cmd={cmd[:220]}", flush=True)
            for ch in sorted(children.get(pid, [])):
                q.append((ch, depth+1))
    for pid in ['81212','84156']:
        try:
            lsof = subprocess.check_output(['lsof','-nP','-a','-p',pid,'-iTCP'], text=True, errors='replace', stderr=subprocess.STDOUT)
            for line in lsof.splitlines()[1:]:
                print('TCP', line[:240], flush=True)
        except subprocess.CalledProcessError:
            pass
    time.sleep(0.5)
