+          status: response.status,
+          model: response.model,
+          usage: response.usage,
+          assistantText: [],
+          reasoningText: [],
+          tools: [],
+        };
+
+        if (Array.isArray(response.output)) {
+          for (const item of response.output) {
+            snapshot.assistantText.push(...collectOutputTextFromItem(item));
