  if (pathname === "/v1") {
    return UPSTREAM_BASE_PATH;
  }

  if (pathname.startsWith("/v1/")) {
    return `${UPSTREAM_BASE_PATH}${pathname.slice(3)}`;
  }

  if (pathname === "/") {
    return UPSTREAM_BASE_PATH;
  }

  return `${UPSTREAM_BASE_PATH}${pathname.startsWith("/") ? pathname : `/${pathname}`}`;
