}

function appendLiveChunk(capture: StreamCapture, kind: "reasoning" | "text", chunk: string | undefined) {
  if (typeof chunk !== "string" || chunk.length === 0) return;

  if (kind === "reasoning") {
    capture.reasoning.push(chunk);
  } else {
