  let o; try { o = JSON.parse(line); } catch { continue; }
  const e = o.event || {};
  const r = e.response;
  if (r && typeof r === 'object') {
    if (typeof r.model === 'string') models.set(r.model, (models.get(r.model)||0)+1);
    if (typeof r.id === 'string') ids.set(r.id, (ids.get(r.id)||0)+1);
    if (typeof r.prompt_cache_key === 'string') cacheKeys.set(r.prompt_cache_key, (cacheKeys.get(r.prompt_cache_key)||0)+1);
