const fs = require('fs');
const crypto = require('crypto');
const digest = (s) => crypto.createHash('sha256').update(s).digest('hex').slice(0,12);
const events = fs.readFileSync('/tmp/codex-proxy-events.ndjson','utf8').trim().split('\n').map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean);
const api = fs.readFileSync('/tmp/codex-proxy-api-json.ndjson','utf8').trim().split('\n').map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean);
const produced = new Map();
for (const o of events) {
  const item = o.event?.item;
  if (item?.type === 'reasoning' && typeof item.encrypted_content === 'string' && o.event?.type === 'response.output_item.done') {
    produced.set(digest(item.encrypted_content), {at:o.at, requestId:o.requestId, itemId:item.id, len:item.encrypted_content.length, summaryLen:Array.isArray(item.summary)?JSON.stringify(item.summary).length:0});
  }
}
const replayed = new Map();
for (const o of api) {
  if (o.phase !== 'request.forwarded' && o.phase !== 'request.received') continue;
  const input = o.body?.input;
  if (!Array.isArray(input)) continue;
  input.forEach((item, index) => {
    if (item?.type === 'reasoning' && typeof item.encrypted_content === 'string') {
      const h = digest(item.encrypted_content);
      if (!replayed.has(h)) replayed.set(h, []);
      replayed.get(h).push({at:o.at, requestId:o.requestId, phase:o.phase, index, len:item.encrypted_content.length, summaryLen:Array.isArray(item.summary)?JSON.stringify(item.summary).length:0});
    }
  });
}
const matches = [];
for (const [h, p] of produced) {
  if (replayed.has(h)) matches.push({hash:h, produced:p, firstReplay:replayed.get(h)[0], replayCount:replayed.get(h).length});
}
console.log(JSON.stringify({produced:produced.size, replayed:replayed.size, matched:matches.length, lastMatches:matches.slice(-20)}, null, 2));
