      sse("response.reasoning_text.delta", { item_id: "rs_1", output_index: 0, content_index: 0, delta: "raw " }),
      sse("response.reasoning_text.delta", { item_id: "rs_1", output_index: 0, content_index: 0, delta: "thought" }),
