    session = kernel.session
    data["session"] = {
        "session_id": session.session,
        "key_length": len(session.key) if session.key else 0,
        "key_hex_prefix": session.key[:4].hex() if session.key else None,
        "signature_scheme": getattr(session, "signature_scheme", None),
        "username": getattr(session, "username", None),
        "pid": getattr(session, "pid", None),
    }

    # Parent header (message schema)
    try:
        parent = kernel.get_parent()
        data["parent_header"] = parent
    except Exception as e:
        data["parent_header_error"] = str(e)

