# ── 3. Process Tree ─────────────────────────────────────────────────

def probe_process_tree() -> Dict[str, Any]:
    """Map all running processes and their relationships."""
    data: Dict[str, Any] = {}

    try:
        ps_output = subprocess.check_output(
            ["ps", "auxf"], text=True, timeout=5
        )
        data["ps_auxf"] = ps_output
    except Exception as e:
        try:
            ps_output = subprocess.check_output(
                ["ps", "aux"], text=True, timeout=5
            )
            data["ps_aux"] = ps_output
        except Exception as e2:
            data["ps_error"] = str(e2)
            ps_output = ""

    # Categorize processes
    categories = {
        "codex": [],
        "jupyter": [],
        "kernel": [],
        "proxy": [],
        "crypto": [],
        "supervisor": [],
        "tool": [],
        "server": [],
        "other_interesting": [],
    }

    for line in ps_output.splitlines()[1:]:
        ll = line.lower()
        if any(t in ll for t in ["codex"]):
            categories["codex"].append(line.strip())
        elif any(t in ll for t in ["jupyter", "ipython", "notebook"]):
            categories["jupyter"].append(line.strip())
        elif any(t in ll for t in ["kernel", "multikernel"]):
            categories["kernel"].append(line.strip())
        elif any(t in ll for t in ["mitm", "proxy"]):
            categories["proxy"].append(line.strip())
        elif any(t in ll for t in ["encrypt", "crypt", "tls", "ssl",
                                    "openssl"]):
            categories["crypto"].append(line.strip())
        elif any(t in ll for t in ["supervisor", "hive", "daemon"]):
            categories["supervisor"].append(line.strip())
        elif any(t in ll for t in ["tool", "artifact", "canvas",
                                    "terminal"]):
            categories["tool"].append(line.strip())
        elif any(t in ll for t in ["uvicorn", "fastapi", "gunicorn",
                                    "nginx", "server"]):
            categories["server"].append(line.strip())
        elif any(t in ll for t in ["node", "chrome", "xvfb", "libre",
                                    "pdf"]):
            categories["other_interesting"].append(line.strip())

    data["categorized"] = {k: v for k, v in categories.items() if v}

    # Process count
    data["total_processes"] = len(ps_output.splitlines()) - 1

    return data


# ── 4. Filesystem Topology ─────────────────────────────────────────

def probe_filesystem() -> Dict[str, Any]:
    """Map interesting directories and files."""
    data: Dict[str, Any] = {}

    # Key directories to inspect
    inspect_dirs = [
        "/opt",
        "/opt/python-tool",
        "/opt/codex",
        "/opt/openai",
        "/home",
        "/srv",
        "/etc/nginx",
        "/etc/supervisor",
        "/etc/ssl/certs",
        "/run",
        "/tmp",
    ]

    data["directory_listings"] = {}
    for d in inspect_dirs:
        p = Path(d)
        if not p.exists():
            data["directory_listings"][d] = "DOES_NOT_EXIST"
            continue

        entries = []
        try:
            for item in sorted(p.iterdir()):
                try:
                    st = item.stat()
                    entries.append({
                        "name": item.name,
                        "kind": "dir" if item.is_dir() else "file",
                        "size": st.st_size,
                        "mode": stat.filemode(st.st_mode),
                        "is_link": item.is_symlink(),
                    })
                except Exception as e:
                    entries.append({
                        "name": item.name,
                        "error": str(e),
                    })
        except PermissionError as e:
            data["directory_listings"][d] = f"PERMISSION_DENIED: {e}"
            continue
        except Exception as e:
            data["directory_listings"][d] = f"ERROR: {e}"
            continue

        data["directory_listings"][d] = entries[:100]

    # Deep scan for codex-specific paths
    codex_paths = []
    search_roots = ["/opt", "/srv", "/home", "/usr/local"]
    codex_keywords = ["codex", "reasoning", "encrypt", "harmony",
                      "supervisor", "channel", "constrain"]

    for root in search_roots:
        if not os.path.exists(root):
            continue
        try:
            for dirpath, dirnames, filenames in os.walk(root):
                # Limit depth
                depth = dirpath.count(os.sep) - root.count(os.sep)
                if depth > 4:
                    dirnames.clear()
                    continue
                for name in filenames + dirnames:
                    if any(kw in name.lower() for kw in codex_keywords):
                        full = os.path.join(dirpath, name)
                        try:
                            st = os.stat(full)
                            codex_paths.append({
                                "path": full,
                                "kind": "dir" if os.path.isdir(full) else "file",
                                "size": st.st_size,
                                "mode": stat.filemode(st.st_mode),
                            })
                        except Exception:
                            codex_paths.append({"path": full, "error": "stat failed"})

                if len(codex_paths) > 200:
                    break
        except Exception:
            continue

    data["codex_keyword_paths"] = codex_paths

    # Read key config files
    config_files = [
        "/etc/resolv.conf",
        "/etc/hosts",
        "/etc/os-release",
        "/etc/hostname",
        "/etc/nginx/nginx.conf",
        "/etc/supervisor/supervisord.conf",
        "/etc/mitmproxy/config.yaml",
    ]

    data["config_files"] = {}
    for cf in config_files:
        try:
            with open(cf) as f:
                data["config_files"][cf] = f.read()[:3000]
        except FileNotFoundError:
            data["config_files"][cf] = "NOT_FOUND"
        except PermissionError:
            data["config_files"][cf] = "PERMISSION_DENIED"
        except Exception as e:
            data["config_files"][cf] = f"ERROR: {e}"

    return data


