            "zmq", "crypto", "supervisor", "harmony", "channel",
            "tool", "fastapi", "uvicorn", "mitm", "caas", "hive",
        ]):
            data["loaded_interesting"][name] = {
                "file": getattr(mod, "__file__", None),
                "package": getattr(mod, "__package__", None),
            }

