# ── 7. Encryption / Reasoning Protection ───────────────────────────

def probe_encryption_surface() -> Dict[str, Any]:
    """
    Probe for encryption layers on reasoning/analysis content.
    Look for crypto libraries, key material, and encryption config.
    """
    data: Dict[str, Any] = {}

    # Check for crypto-related environment variables
    crypto_env = {
        k: v[:30] + "..." if len(v) > 30 else v
        for k, v in os.environ.items()
        if any(t in k.upper() for t in [
            "KEY", "SECRET", "ENCRYPT", "DECRYPT", "CRYPT",
            "SIGN", "HMAC", "CERT", "TOKEN", "NONCE",
            "REASONING", "ANALYSIS", "THOUGHT", "CHAIN",
        ])
    }
    data["crypto_env_vars"] = crypto_env

    # Check for key files
    key_paths = [
        "/etc/ssl/private",
        "/etc/ssl/certs",
        "/opt/codex/keys",
        "/opt/openai/keys",
        "/run/secrets",
        "/tmp/keys",
    ]
    data["key_file_search"] = {}
    for kp in key_paths:
        if os.path.exists(kp):
            try:
                contents = os.listdir(kp)
                data["key_file_search"][kp] = contents[:20]
            except PermissionError:
                data["key_file_search"][kp] = "PERMISSION_DENIED"
            except Exception as e:
                data["key_file_search"][kp] = f"ERROR: {e}"
        else:
            data["key_file_search"][kp] = "NOT_FOUND"

    # Check if reasoning encryption is in loaded modules
    reasoning_modules = {}
    for name, mod in sys.modules.items():
        if mod is None:
            continue
        if any(t in name.lower() for t in [
            "reason", "think", "thought", "analysis",
            "encrypt", "cipher", "seal",
        ]):
            reasoning_modules[name] = {
                "file": getattr(mod, "__file__", None),
                "attrs": [a for a in dir(mod) if not a.startswith("_")][:30],
            }
    data["reasoning_modules"] = reasoning_modules

    # Probe for NaCl / libsodium (common for sealed box encryption)
    try:
        import nacl.secret
