            data[f"jwt_{jwt_mod}"] = {
                "available": True,
                "version": getattr(mod, "__version__", "?"),
            }
        except ImportError:
            data[f"jwt_{jwt_mod}"] = {"available": False}

    # Probe tiktoken for harmony encoding
    try:
        import tiktoken
        data["tiktoken"] = {
            "available": True,
            "version": tiktoken.__version__,
            "encodings": (
                tiktoken.list_encoding_names()
                if hasattr(tiktoken, "list_encoding_names") else []
            ),
        }

        # Check for harmony encoding
        if "o200k_harmony" in data["tiktoken"].get("encodings", []):
            data["tiktoken"]["harmony_available"] = True
            try:
