# ── 8. Inter-Process Communication ──────────────────────────────────

def probe_ipc() -> Dict[str, Any]:
    """Probe IPC mechanisms: unix sockets, shared memory, pipes."""
    data: Dict[str, Any] = {}

    # Unix domain sockets from /proc/net/unix
    try:
        with open("/proc/net/unix") as f:
            unix_sockets = f.read()
        # Filter for interesting ones
        interesting = []
        for line in unix_sockets.splitlines()[1:]:
            parts = line.split()
            if len(parts) >= 8:
                path = parts[-1] if not parts[-1].startswith("[") else ""
                if path and any(t in path.lower() for t in [
                    "codex", "jupyter", "kernel", "zmq", "tool",
                    "supervisor", "openai", "ipc", "sock",
                ]):
                    interesting.append({
                        "path": path,
                        "state": parts[5] if len(parts) > 5 else "?",
                    })
            elif len(parts) >= 7:
                # Socket without path (abstract namespace)
                interesting.append({
                    "path": "(abstract)",
                    "raw": line.strip()[:200],
                })

        data["unix_sockets_interesting"] = interesting[:50]
        data["unix_sockets_total"] = len(unix_sockets.splitlines()) - 1
    except Exception as e:
        data["unix_sockets_error"] = str(e)

    # Shared memory segments
    try:
        shm_path = Path("/dev/shm")
        if shm_path.exists():
            shm_contents = []
            for item in sorted(shm_path.iterdir()):
                try:
                    st = item.stat()
                    shm_contents.append({
                        "name": item.name,
                        "size": st.st_size,
                        "mode": stat.filemode(st.st_mode),
                    })
                except Exception:
                    shm_contents.append({"name": item.name, "error": "stat"})
            data["shared_memory"] = shm_contents[:30]
    except Exception as e:
        data["shared_memory_error"] = str(e)

    # Named pipes (FIFOs)
    fifo_search = ["/tmp", "/run", "/var/run"]
    fifos = []
    for search_dir in fifo_search:
        try:
            for item in Path(search_dir).rglob("*"):
                try:
                    if stat.S_ISFIFO(item.stat().st_mode):
                        fifos.append(str(item))
                except Exception:
                    pass
                if len(fifos) > 20:
                    break
        except Exception:
            pass
    data["named_pipes"] = fifos

    return data


