        port_results: Dict[str, Any] = {}

        for path in discovery_paths:
            url = base + path
            try:
                r = req.get(url, timeout=2)
                entry: Dict[str, Any] = {
                    "status": r.status_code,
                    "content_type": r.headers.get("content-type", ""),
                    "server": r.headers.get("server", ""),
                    "size": len(r.text),
                }

                # Try to parse JSON
                if "json" in r.headers.get("content-type", "").lower():
                    try:
                        entry["json"] = r.json()
                    except Exception:
                        entry["body_preview"] = r.text[:500]
                elif r.status_code == 200:
                    entry["body_preview"] = r.text[:500]

                # Special handling for OpenAPI spec
                if path == "/openapi.json" and r.status_code == 200:
                    try:
                        spec = r.json()
                        entry["openapi_version"] = spec.get("openapi")
                        entry["api_title"] = spec.get("info", {}).get("title")
                        entry["paths"] = list(spec.get("paths", {}).keys())
                    except Exception:
                        pass

                port_results[path] = entry

            except req.exceptions.ConnectionError:
                # Port not responding — skip remaining paths
                port_results["_connection_error"] = True
                break
            except req.exceptions.Timeout:
                port_results[path] = {"timeout": True}
            except Exception as e:
                port_results[path] = {"error": str(e)}

        if port_results and not port_results.get("_connection_error"):
            data["service_discovery"][port] = port_results

    return data


