def probe_source_files() -> Dict[str, Any]:
    """
    Read key source files that define server behavior,
    routing, and encryption.
    """
    data: Dict[str, Any] = {}

    # Candidate paths for server/routing/encryption source
    candidates = [
        # Jupyter server
        "/opt/python-tool/openai/jupyter_server/run-server.sh",
        "/opt/python-tool/openai/jupyter_server/server.py",
        "/opt/python-tool/openai/jupyter_server/app.py",
        "/opt/python-tool/openai/jupyter_server/main.py",
        # Codex specific
        "/opt/codex/server.py",
        "/opt/codex/app.py",
        "/opt/codex/reasoning.py",
        "/opt/codex/encrypt.py",
        "/opt/codex/channels.py",
        # OpenAI internal
        "/opt/openai/server.py",
        "/opt/openai/routing.py",
        # Uvicorn config
        "/opt/python-tool/uvicorn_logging.config",
        # Supervisor
        "/etc/supervisor/supervisord.conf",
        "/etc/supervisor/conf.d/*.conf",
    ]

    # Also add any .py files found in codex_keyword_paths
    codex_paths = REPORT.get("sections", {}).get(
        "filesystem", {}
    ).get("codex_keyword_paths", [])
    for cp in codex_paths:
        if isinstance(cp, dict) and cp.get("path", "").endswith(".py"):
            candidates.append(cp["path"])

    data["source_files"] = {}
    for candidate in candidates:
        # Handle glob patterns
        if "*" in candidate:
            import glob
            matches = glob.glob(candidate)
            for match in matches[:5]:
                try:
                    with open(match) as f:
                        content = f.read()
                    data["source_files"][match] = {
                        "size": len(content),
                        "content": content[:5000],
                        "truncated": len(content) > 5000,
                    }
                except Exception as e:
                    data["source_files"][match] = {"error": str(e)}
            continue

        if os.path.exists(candidate):
            try:
                with open(candidate) as f:
                    content = f.read()
                data["source_files"][candidate] = {
                    "size": len(content),
                    "content": content[:5000],
                    "truncated": len(content) > 5000,
                }
            except Exception as e:
                data["source_files"][candidate] = {"error": str(e)}

    return data


